import{_ as a,o as i,c as o,ag as t}from"./chunks/framework.D--JA8_b.js";const u=JSON.parse('{"title":"域名到期与AI编程：从折腾三天到半小时搞定","description":"","frontmatter":{},"headers":[],"relativePath":"posts/2026-05-21-domain-migration-ai-coding.md","filePath":"posts/2026-05-21-domain-migration-ai-coding.md","lastUpdated":1779363344000}'),l={name:"posts/2026-05-21-domain-migration-ai-coding.md"};function r(n,e,d,p,x,s){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="域名到期与ai编程-从折腾三天到半小时搞定" tabindex="-1">域名到期与AI编程：从折腾三天到半小时搞定 <a class="header-anchor" href="#域名到期与ai编程-从折腾三天到半小时搞定" aria-label="Permalink to &quot;域名到期与AI编程：从折腾三天到半小时搞定&quot;">​</a></h1><p>发布时间：2026-05-21 · 标签：#域名迁移 #ClaudeCode #AI编程 #V2ray #SSL</p><hr><p>前几天收到域名续费提醒，一看价格差点没绷住——<code>xxxxxxxxx.site</code> 每年要91块。一个 <code>.site</code> 域名卖这么贵，抢钱呢？</p><p>果断不续了。随手一搜，发现 <code>.online</code> 域名十年才230块，平均一年23，四舍五入等于白送。直接下单十年，划算到离谱。</p><h2 id="问题来了" tabindex="-1">问题来了 <a class="header-anchor" href="#问题来了" aria-label="Permalink to &quot;问题来了&quot;">​</a></h2><p>域名买了，但服务器上跑的全是旧域名的配置。Nginx、V2ray、SSL证书，全都绑着 <code>xxxxxxxxx.site</code>。要换域名，意味着：</p><ul><li>重新申请 SSL 证书</li><li>改 Nginx 的 <code>server_name</code></li><li>改 V2ray 的证书路径和域名配置</li><li>处理证书权限问题（V2ray 用 <code>nobody</code> 用户跑，读不了 root 权限的 Let&#39;s Encrypt 私钥）</li><li>配置证书自动续期的同步脚本</li><li>客户端全部换地址</li></ul><p>这些东西，放在以前，我少说也得折腾两三天。SSH 上去，一个个配置文件改，测试，重启，排查，再测试……光是 Let&#39;s Encrypt 的申请和权限调试，就能耗掉一个下午。</p><h2 id="半小时搞定" tabindex="-1">半小时搞定 <a class="header-anchor" href="#半小时搞定" aria-label="Permalink to &quot;半小时搞定&quot;">​</a></h2><p>今天打开 Claude Code，就丢了一句话过去：</p><blockquote><p>我域名从 xxxxxxxxx.site 换成 xxxxxxxxx.online 了，服务器上的 V2ray 和网站配置都要改，SSL 证书也重新弄一下。</p></blockquote><p>然后它就自己开始干活了。</p><ul><li>自动 SSH 连上服务器</li><li>查看现有的 Nginx、V2ray、Certbot 配置</li><li>发现证书路径、server_name、权限等五个问题</li><li>用 certbot 申请新证书</li><li>把证书复制到 V2ray 能读的位置，改好权限</li><li>更新 V2ray 和 Nginx 配置</li><li>写了自动续期的 deploy hook</li><li>重启服务，验证端口和 HTTPS</li></ul><p>全程我没敲一行命令，没打开一个配置文件。就在旁边看着，偶尔确认一下。</p><p><strong>半小时，全部搞定。</strong></p><p>想起当初第一次搭这个服务器，从装系统到配 Nginx、V2ray、SSL，硬是折腾了三四天。那时候每一步都要查文档、踩坑、debug。今天倒好，动动嘴，AI 帮我全干了。</p><h2 id="一点感慨" tabindex="-1">一点感慨 <a class="header-anchor" href="#一点感慨" aria-label="Permalink to &quot;一点感慨&quot;">​</a></h2><p>以前编程是&quot;我知道怎么做，但得花时间去敲&quot;。</p><p>以后可能是&quot;我有个想法，AI 帮我实现&quot;——我只用判断对不对、好不好，剩下的交给它。</p><p>就像科幻电影里那种场景：飞船快散架了，只要主机还能开机，AI 就能自动代码重构，检测硬件，把现有的破烂设备全部重新调度跑起来。以前觉得那是几百年后的未来，现在想想，好像也不远了。</p><p>Awesome！</p><hr><p><em>本文使用 Claude Code 智能助手协助撰写</em></p>',24)])])}const h=a(l,[["render",r]]);export{u as __pageData,h as default};
